// Deterministic force layout for entity graphs. A port of backend/app/outputs/graph_layout.py:
// the same arithmetic in the same order on IEEE doubles, so the incident graph here and the graph
// in the report PDF place every node at the same position. graph.fixture.json is generated by the
// Python module and checked by both test suites.

export const ITERATIONS = 150;
export const PAD = 16;
const GRAVITY = 0.02;

/** 32-bit FNV-1a over UTF-16 code units. */
export function fnv1a(text: string): number {
  let h = 0x811c9dc5;
  for (let i = 0; i < text.length; i++) {
    h = (h ^ text.charCodeAt(i)) >>> 0;
    h = Math.imul(h, 0x01000193) >>> 0;
  }
  return h;
}

export interface Placed {
  id: string;
  x: number;
  y: number;
}

export function layout(nodeIds: readonly string[], edges: ReadonlyArray<readonly [string, string]>, width: number, height: number, iterations = ITERATIONS): Placed[] {
  const n = nodeIds.length;
  if (n === 0) return [];
  const index = new Map<string, number>();
  nodeIds.forEach((id, i) => index.set(id, i));
  const w = width - 2 * PAD;
  const h = height - 2 * PAD;
  const xs: number[] = [];
  const ys: number[] = [];
  for (const id of nodeIds) {
    const hv = fnv1a(id);
    xs.push(PAD + ((hv & 0xffff) / 65535) * w);
    ys.push(PAD + ((hv >>> 16) / 65535) * h);
  }
  if (n === 1) return [{ id: nodeIds[0]!, x: width / 2, y: height / 2 }];
  const k = Math.sqrt((w * h) / n);
  const pairs: Array<[number, number]> = [];
  for (const [a, b] of edges) {
    const ia = index.get(a);
    const ib = index.get(b);
    if (ia !== undefined && ib !== undefined && a !== b) pairs.push([ia, ib]);
  }
  const cx = width / 2;
  const cy = height / 2;
  const t0 = w / 10;
  const dx = new Array<number>(n);
  const dy = new Array<number>(n);
  for (let it = 0; it < iterations; it++) {
    dx.fill(0);
    dy.fill(0);
    for (let i = 0; i < n; i++) {
      for (let j = i + 1; j < n; j++) {
        let ddx = xs[i]! - xs[j]!;
        let ddy = ys[i]! - ys[j]!;
        let d2 = ddx * ddx + ddy * ddy;
        if (d2 < 1e-9) {
          ddx = 0.01 * (i - j);
          ddy = 0.01;
          d2 = ddx * ddx + ddy * ddy;
        }
        const d = Math.sqrt(d2);
        const f = (k * k) / d;
        const fx = (ddx / d) * f;
        const fy = (ddy / d) * f;
        dx[i]! += fx;
        dy[i]! += fy;
        dx[j]! -= fx;
        dy[j]! -= fy;
      }
    }
    for (const [a, b] of pairs) {
      const ddx = xs[a]! - xs[b]!;
      const ddy = ys[a]! - ys[b]!;
      const d = Math.sqrt(ddx * ddx + ddy * ddy);
      if (d < 1e-9) continue;
      const f = (d * d) / k;
      const fx = (ddx / d) * f;
      const fy = (ddy / d) * f;
      dx[a]! -= fx;
      dy[a]! -= fy;
      dx[b]! += fx;
      dy[b]! += fy;
    }
    const temp = t0 * (1 - it / iterations);
    for (let i = 0; i < n; i++) {
      dx[i]! -= (xs[i]! - cx) * GRAVITY * k;
      dy[i]! -= (ys[i]! - cy) * GRAVITY * k;
      const length = Math.sqrt(dx[i]! * dx[i]! + dy[i]! * dy[i]!);
      if (length > 0) {
        const step = length < temp ? length : temp;
        xs[i]! += (dx[i]! / length) * step;
        ys[i]! += (dy[i]! / length) * step;
      }
      xs[i] = xs[i]! < PAD ? PAD : xs[i]! > width - PAD ? width - PAD : xs[i]!;
      ys[i] = ys[i]! < PAD ? PAD : ys[i]! > height - PAD ? height - PAD : ys[i]!;
    }
  }
  return nodeIds.map((id, i) => ({ id, x: xs[i]!, y: ys[i]! }));
}
